const MaterialDigestUnreadable = "unreadable"

// MaterialBindingUnavailable is recorded for a scope whose material cannot be
// established, so the result is stale for it instead of falling back to the
// commit-bound rules.
const MaterialBindingUnavailable = "unavailable"

// MaterialBinding returns what a validation run should record for a spec: the
// scoped digest, the unavailable marker when a change set's material could not
// be read, or nothing when the spec has no material-bound change set.
func MaterialBinding(graph DeliveryIntegrityGraph, spec string) (string, bool) {
	sets := 0
	for _, set := range graph.ChangeSets {
		if set.Spec != spec {
			continue
		}
		sets++
		// A set read back from the report history carries no material digest, and
		// one that could not be read has the unreadable marker: either way the
		// scope's material cannot be established, so the run records the binding as
		// unavailable instead of silently falling back to the commit-bound rules.
		if set.MaterialDigest == "" || set.MaterialDigest == MaterialDigestUnreadable {
			return MaterialBindingUnavailable, true
		}
	}
	if sets == 0 {
		return "", false
	}
	if digest := ScopedMaterialDigest(graph, spec); digest != "" {
		return digest, true
	}
	return "", false
}

// ScopedMaterialDigest binds evidence to the claims and material of one spec's
// change sets and to the engine. It is empty when any change set has no
// material digest, so no binding can be recorded for it.
func ScopedMaterialDigest(graph DeliveryIntegrityGraph, spec string) string {
	claims := []ArtifactClaim{}
	digests := []string{}
	for _, claim := range graph.Claims {
		if claim.Spec == spec {
			claims = append(claims, claim)
		}
	}
	for _, set := range graph.ChangeSets {
		if set.Spec != spec {
			continue
		}
		if set.MaterialDigest == "" || set.MaterialDigest == MaterialDigestUnreadable {
			return ""
		}
		digests = append(digests, set.MaterialDigest)
	}
	if len(digests) == 0 {
		return ""
	}
	sort.Slice(claims, func(i, j int) bool { return claimKey(claims[i]) < claimKey(claims[j]) })
	sort.Strings(digests)
	raw, _ := json.Marshal(struct {
		Engine string          `json:"engine"`
		Claims []ArtifactClaim `json:"claims"`
		Digest []string        `json:"material"`
	}{engineVersion, claims, digests})
	sum := sha256.Sum256(raw)
	return "sha256:" + hex.EncodeToString(sum[:])
}

// withoutMaterialDigest copies change sets without the material digest, so the
// commit-bound digests keep the representation results were recorded against.
func withoutMaterialDigest(sets []ChangeSet) []ChangeSet {
	out := make([]ChangeSet, len(sets))
	for i, set := range sets {
		set.MaterialDigest = ""
		set.MaterialInputs = nil
		out[i] = set
	}
	return out
}

// CurrentMaterialDigests recomputes the material digest of each set from its
// stored inputs against the current tree, through the hook the binary
// registered. Evidence is judged against these, not against the digests the
// persisted index recorded when it was built: an untrailered commit after the
// index changes what the evidence describes (spec
// pose-validation-evidence-material-binding R6). A set without inputs, or a
// binary without a hook, keeps the recorded digest.
var CurrentMaterialDigests func(root string, inputs MaterialInputs) string

// SetCurrentMaterialDigests registers the recomputation.
func SetCurrentMaterialDigests(f func(root string, inputs MaterialInputs) string) {
	CurrentMaterialDigests = f
}

func withCurrentMaterial(root string, sets []ChangeSet) []ChangeSet {
	if CurrentMaterialDigests == nil {
		return sets
	}
	out := make([]ChangeSet, len(sets))
	for i, set := range sets {
		if set.MaterialInputs != nil && set.MaterialDigest != "" && set.MaterialDigest != MaterialDigestUnreadable {
			set.MaterialDigest = CurrentMaterialDigests(root, *set.MaterialInputs)
		}
		out[i] = set
	}
	return out
}

