func TestFactResultKeySeparatesMaterialBindings(t *testing.T) {
	a := DeliveryValidationResult{ID: "x", MaterialProvenance: map[string]string{"s": "sha256:1"}}
	b := DeliveryValidationResult{ID: "x", MaterialProvenance: map[string]string{"s": "sha256:2"}}
	if factResultKey(a) == factResultKey(b) {
		t.Fatal("two material bindings share one identity")
	}
}

func TestARecordedSetWithoutAMaterialDigestMakesTheBindingUnavailable(t *testing.T) {
	g := DeliveryIntegrityGraph{ChangeSets: []ChangeSet{
		{ID: "cs-1", Spec: "s", MaterialDigest: "sha256:m"},
		{ID: "cs-recorded", Spec: "s"},
	}}
	if got, ok := MaterialBinding(g, "s"); !ok || got != MaterialBindingUnavailable {
		t.Fatalf("got %q %v", got, ok)
	}
	if _, ok := MaterialBinding(g, "other"); ok {
		t.Fatal("a spec without change sets records no binding")
	}
}

func TestCodeInsideAnAdministrativeClassIsMaterial(t *testing.T) {
	for p, want := range map[string]bool{
		".pose/results/report.json":      true,
		".pose/state/history.jsonl":      true,
		".pose/assessments/pose-mcp.md":  true,
		".pose/review-runs/x.transcript": true,
		".pose/results/helper.go":        false,
		".pose/results/build-backlog.py": false,
		".pose/indexes/refresh.sh":       false,
		".pose/results/noextension":      false,
	} {
		if got := IsAdministrativePath(p); got != want {
			t.Errorf("%q: got %v want %v", p, got, want)
		}
	}
	// Editing a source file placed in a class moves the digest.
	paths := []ObservedPath{obs("A", ".pose/results/helper.go")}
	one := MaterialSetDigest(MaterialInputsOf(paths), map[string]TreeEntry{".pose/results/helper.go": regularEntry("b1")})
	two := MaterialSetDigest(MaterialInputsOf(paths), map[string]TreeEntry{".pose/results/helper.go": regularEntry("b2")})
	if one == two {
		t.Fatal("editing code inside a class kept the digest")
	}
}

func TestEvidenceIsJudgedAgainstTheCurrentMaterial(t *testing.T) {
	in := MaterialInputsOf([]ObservedPath{obs("M", "a.go")})
	g := materialGraph("h1", "sha256:indexed")
	g.ChangeSets[0].MaterialInputs = &in
	result := DeliveryValidationResult{GitHead: "h1", MaterialProvenance: map[string]string{"s": ScopedMaterialDigest(g, "s")}}

	defer SetCurrentMaterialDigests(nil)
	SetCurrentMaterialDigests(func(string, MaterialInputs) string { return "sha256:indexed" })
	same := materialGraph("h1", "sha256:indexed")
	same.ChangeSets = withCurrentMaterial("/x", g.ChangeSets)
	if !deliveryEvidenceCurrent(result, "s", "in-progress", same, same.ChangeSets) {
		t.Fatal("an unchanged tree made current evidence stale")
	}
	// An untrailered commit changed an observed path after the index was built.
	SetCurrentMaterialDigests(func(string, MaterialInputs) string { return "sha256:after-the-index" })
	moved := materialGraph("h1", "sha256:indexed")
	moved.ChangeSets = withCurrentMaterial("/x", g.ChangeSets)
	if deliveryEvidenceCurrent(result, "s", "in-progress", moved, moved.ChangeSets) {
		t.Fatal("the persisted index vouched for a tree that changed after it was built")
	}
}

func TestLegacyDigestsIgnoreTheMaterialFields(t *testing.T) {
	plain := materialGraph("h1", "")
	rich := materialGraph("h1", "sha256:m")
	rich.ChangeSets[0].MaterialInputs = &MaterialInputs{Names: []string{"a.go"}, Moved: []string{"b.go"}}
	if ScopedDeliveryProvenanceDigest(plain, "s") != ScopedDeliveryProvenanceDigest(rich, "s") {
		t.Fatal("the scoped provenance digest moved with the material inputs")
	}
	if string(mustJSON(t, withoutMaterialDigest(rich.ChangeSets))) != string(mustJSON(t, withoutMaterialDigest(plain.ChangeSets))) {
		t.Fatal("the commit-bound representation of a change set kept a material field")
	}
}

func mustJSON(t *testing.T, v any) []byte {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

